        borderColor: "#000000",
        pointBackgroundColor: "#000000",
        pointBorderColor: "#000000",
        pointRadius: 4,
        pointHoverRadius: 10,
        pointHoverBorderWidth: 3,
        pointBorderWidth: 7,
        borderWidth: 5,
        tension: 0.4,
        pointHoverBackgroundColor: "#000000",
        pointHoverBorderColor: "#000000",
        _rawData: data,
        _rateUnit: rateUnit,
